export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

/**
 * Moves an issue into another project of the same workspace.
 *
 * Requires `issue:update` on the issue and `issue:create` on the target, and
 * the target's per-project issue quota applies exactly as it does for a new
 * issue. A same-project move changes nothing and publishes nothing. A refusal
 * writes nothing. The move publishes `issue.moved` only — not a create, an
 * edit, or an archive — and the issue keeps every field other than its
 * project and its number.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const target = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertCan(actor, "issue:create", projectResource(target));

  if (issue.projectId === target.id) {
    return issue;
  }

  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Project", target.id, target);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, target.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${target.key}`,
    );
  }

  const moved = await issueRepo.reassignIssueToProject(
    input.orgId,
    issue.id,
    target.id,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: moved.id,
    fromProjectId: issue.projectId,
    toProjectId: moved.projectId,
    fromNumber: issue.number,
    toNumber: moved.number,
  });

  return moved;
}

