import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movecheck", "free");
  registerActivityListeners();
  registerSearchListeners();
});

afterAll(() => {
  cleanup();
});

describe("moveIssueToProject", () => {
  it("moves, renumbers, retires, audits, indexes, and no-ops same project", async () => {
    const target = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "keep-me",
      color: "#94a3b8",
      description: null,
    });

    const first = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "First stays" }),
    );
    const moving = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title: "Move me please",
        assigneeId: tenant.userIds.admin,
      }),
      description: "body stays",
      priority: "high",
      estimate: 3,
      labelIds: [label.id],
    });
    const third = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Third stays" }),
    );

    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: moving.id,
      body: "comment stays",
      parentId: null,
      mentionedUserIds: [],
    });

    const createdEvents: string[] = [];
    const updatedEvents: string[] = [];
    const movedEvents: unknown[] = [];
    const offCreated = subscribe("issue.created", () => {
      createdEvents.push("c");
    });
    const offUpdated = subscribe("issue.updated", () => {
      updatedEvents.push("u");
    });
    const offMoved = subscribe("issue.moved", (payload) => {
      movedEvents.push(payload);
    });

    const same = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: moving.id,
      toProjectId: tenant.project.id,
    });
    expect(same.number).toBe(moving.number);
    expect(same.projectId).toBe(tenant.project.id);
    expect(movedEvents).toHaveLength(0);

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: moving.id,
      toProjectId: target.id,
    });

    expect(moved.id).toBe(moving.id);
    expect(moved.projectId).toBe(target.id);
    expect(moved.number).toBe(1);
    expect(moved.title).toBe("Move me please");
    expect(moved.description).toBe("body stays");
    expect(moved.status).toBe("backlog");
    expect(moved.priority).toBe("high");
    expect(moved.assigneeId).toBe(tenant.userIds.admin);
    expect(moved.estimate).toBe(3);
    expect(moved.labelIds).toEqual([label.id]);
    expect(moved.authorId).toBe(moving.authorId);
    expect(createdEvents).toHaveLength(0);
    expect(updatedEvents).toHaveLength(0);
    expect(movedEvents).toHaveLength(1);
    expect(movedEvents[0]).toMatchObject({
      actorId: tenant.userIds.member,
      orgId: tenant.org.id,
      issueId: moving.id,
      fromProjectId: tenant.project.id,
      toProjectId: target.id,
      fromNumber: 2,
      toNumber: 1,
    });

    const stored = await issueRepo.findIssueById(tenant.org.id, moving.id);
    expect(stored?.projectId).toBe(target.id);
    expect(stored?.number).toBe(1);
    expect(stored?.labelIds).toEqual([label.id]);

    const comments = await commentRepo.listComments(tenant.org.id, moving.id, {
      limit: 10,
      cursor: null,
    });
    expect(comments.items.map((c) => c.body)).toEqual(["comment stays"]);

    const sourceList = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      limit: 25,
      cursor: null,
    });
    expect(sourceList.items.map((i) => i.id).sort()).toEqual(
      [first.id, third.id].sort(),
    );

    const targetList = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: target.id,
      limit: 25,
      cursor: null,
    });
    expect(targetList.items.map((i) => i.id)).toEqual([moving.id]);

    const sourceBoard = await issueService.getBoard(
      tenant.actors.member,
      tenant.org.id,
      tenant.project.id,
    );
    const targetBoard = await issueService.getBoard(
      tenant.actors.member,
      tenant.org.id,
      target.id,
    );
    expect(sourceBoard.flatMap((c) => c.issues.map((i) => i.id))).not.toContain(
      moving.id,
    );
    expect(targetBoard.flatMap((c) => c.issues.map((i) => i.id))).toContain(
      moving.id,
    );

    const sourceHits = await search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Move me please",
      kinds: ["issue"],
      projectId: tenant.project.id,
      limit: 10,
      cursor: null,
    });
    const targetHits = await search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Move me please",
      kinds: ["issue"],
      projectId: target.id,
      limit: 10,
      cursor: null,
    });
    expect(sourceHits.total).toBe(0);
    expect(targetHits.items.map((h) => h.id)).toEqual([moving.id]);

    const nextSource = await issueRepo.nextIssueNumber(
      tenant.org.id,
      tenant.project.id,
    );
    expect(nextSource).toBe(4);
    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After move" }),
    );
    expect(created.number).toBe(4);

    const back = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: moving.id,
      toProjectId: tenant.project.id,
    });
    expect(back.number).toBe(5);
    const nextAfterBack = await issueRepo.nextIssueNumber(
      tenant.org.id,
      tenant.project.id,
    );
    expect(nextAfterBack).toBe(6);
    const nextTarget = await issueRepo.nextIssueNumber(tenant.org.id, target.id);
    expect(nextTarget).toBe(2);

    const activity = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.moved"],
      limit: 25,
      cursor: null,
    });
    expect(activity.items).toHaveLength(2);
    expect(activity.items[0]).toMatchObject({
      action: "issue.moved",
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      subjectId: moving.id,
      projectId: tenant.project.id,
      metadata: {
        fromProjectId: target.id,
        toProjectId: tenant.project.id,
        fromNumber: 1,
        toNumber: 5,
      },
    });
    const firstAudit = activity.items.find(
      (row) => row.metadata.fromNumber === 2,
    );
    expect(firstAudit?.projectId).toBe(target.id);
    expect(firstAudit?.metadata).toMatchObject({
      fromProjectId: tenant.project.id,
      toProjectId: target.id,
      fromNumber: 2,
      toNumber: 1,
    });

    const createdAudit = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      projectId: tenant.project.id,
      subjectKind: "issue",
      limit: 25,
      cursor: null,
    });
    expect(
      createdAudit.items.find((row) => row.subjectId === moving.id)?.projectId,
    ).toBe(tenant.project.id);

    offCreated();
    offUpdated();
    offMoved();

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: first.id,
