        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses when the target is at its issue quota and changes nothing", async () => {
    const quotaTenant = await createTenant("movequota", "free");
    const target = await projectService.createProject(quotaTenant.actors.admin, {
      orgId: quotaTenant.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    // free plan allows 2 projects. We have platform + full. Good.
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, target.id, { title: `Seed ${number}` }),
        quotaTenant.actors.member.userId,
        number,
      );
    }
    const issue = await issueService.createIssue(
      quotaTenant.actors.member,
      issueInput(quotaTenant.org.id, quotaTenant.project.id, { title: "Stay put" }),
    );
    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    await expect(
      issueService.moveIssueToProject(quotaTenant.actors.member, {
        orgId: quotaTenant.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toThrow(/allows no more issues/);
    const stored = await issueRepo.findIssueById(quotaTenant.org.id, issue.id);
    expect(stored?.projectId).toBe(quotaTenant.project.id);
    expect(stored?.number).toBe(issue.number);
    expect(seen).toHaveLength(0);
    const next = await issueRepo.nextIssueNumber(quotaTenant.org.id, target.id);
    expect(next).toBe(101);
    off();
  });
});
